def get_panglaodb_markers(
    organ: str | None = None,
    species: str | None = None,
) -> dict[str, list[str]]:
    """Get PanglaoDB markers, optionally filtered by organ and species.

    Args:
        organ: Filter by organ (e.g., "Immune system", "Brain").
        species: Filter by species ("human" or "mouse").

    Returns:
        Dict mapping cell type name → list of marker gene symbols.
    """
    result: dict[str, list[str]] = {}
    search = {organ: PANGLAODB.get(organ, {})} if organ else PANGLAODB
    for organ_dict in search.values():
        for ct, entries in organ_dict.items():
            if species and species not in SPECIES_MAP.get(ct, set()):
                continue
            result[ct] = [g for g, _ in entries]
    return result
